    void setAbilityPercentage( fheroes2::MonsterData & data, const fheroes2::MonsterAbilityType type, const uint32_t percentage )
    {
        for ( fheroes2::MonsterAbility & ability : data.battleStats.abilities ) {
            if ( ability.type == type ) {
                ability.percentage = percentage;
            }
        }
    }

    void removeAbility( fheroes2::MonsterData & data, const fheroes2::MonsterAbilityType type )
    {
        auto & abilities = data.battleStats.abilities;
        abilities.erase( std::remove_if( abilities.begin(), abilities.end(), [type]( const fheroes2::MonsterAbility & a ) { return a.type == type; } ),
                         abilities.end() );
    }
