    int creatureCount()
    {
        return isExtension() ? firstExtensionCreature + extensionCreatureCount : firstExtensionCreature;
    }

    const CreatureRow & creatureRow( const int creature )
    {
        if ( creature >= firstExtensionCreature && creature < firstExtensionCreature + extensionCreatureCount ) {
            return extensionTable[static_cast<size_t>( creature - firstExtensionCreature )];
        }
        if ( creature < 0 || creature >= firstExtensionCreature ) {
            return creatureTable[0];
        }
        return creatureTable[static_cast<size_t>( creature )];
    }

    const char * creatureFile( const int creature )
    {
        return ( creature >= 0 && creature < 40 ) ? allFiles[creature] : "";
    }

    const char * creatureNameOne( const int creature )
    {
        return ( creature >= 0 && creature < 40 ) ? allOne[creature] : "";
    }

    const char * creatureNameMany( const int creature )
    {
        return ( creature >= 0 && creature < 40 ) ? allMany[creature] : "";
    }

    int creatureWorth( const int creature )
    {
        return ( creature >= 0 && creature < 40 ) ? allWorth[creature] : 0;
    }

    const char * smallCreatureIcn( const int creature )
    {
        return ( creature >= firstExtensionCreature ) ? "mons32x.icn" : "mons32.icn";
    }

    int smallCreatureFrame( const int creature )
    {
        return ( creature >= firstExtensionCreature ) ? creature - firstExtensionCreature : creature;
    }

    const char * mapCreatureIcn( const int creature )
    {
        return ( creature >= firstExtensionCreature ) ? "minimonx.icn" : "minimon.icn";
    }

    int mapCreatureFrame( const int creature, const int phase )
    {
        return ( ( creature >= firstExtensionCreature ) ? creature - firstExtensionCreature : creature ) * 7 + phase;
    }

    int creatureExperience( const int creature )
    {
        // 0x491e78 + 8 for 0..27; 28..35 = hit points (as most HoMM1 creatures have it) [adapted].
        static const int experience[28] = { 1, 10, 15, 25, 30, 50, 3, 10, 20, 40, 50, 60, 2, 20, 15, 25, 40, 100, 5, 15, 25, 35, 75, 200, 4, 20, 20, 50 };
        if ( creature >= 0 && creature < 28 ) {
            return experience[creature];
        }
        return ( creature >= 28 && creature < 40 ) ? creatureRow( creature ).hp : 0;
    }

    void applyCreatureRules( std::vector<fheroes2::MonsterData> & monsterData )
    {
        if ( !isH1Mode() ) {
            return;
        }
        // 1. Numbers from the original creature table (v12). Speed is NOT changed here: HoMM1 speed is a 1-4 level on the
        //    9x5 battlefield; it is applied together with the battlefield port (v42 open item).
        for ( const CreatureRow & row : creatureTable ) {
            fheroes2::MonsterData & data = monsterData[row.monsterId];
            fheroes2::MonsterBattleStats & battle = data.battleStats;
            battle.attack = row.attack;
            battle.defense = row.defense;
            battle.damageMin = row.damageMin;
            battle.damageMax = row.damageMax;
            battle.hp = row.hp;
            battle.shots = row.shots;

            fheroes2::MonsterGeneralStats & general = data.generalStats;
            general.baseGrowth = row.growth;
            Cost cost{};
            cost.gold = static_cast<uint16_t>( row.gold );
            switch ( row.extraResource ) {
            case 0: cost.wood = 1; break;
            case 1: cost.mercury = 1; break;
            case 2: cost.ore = 1; break;
            case 3: cost.sulfur = 1; break;
            case 4: cost.crystal = 1; break;
            case 5: cost.gems = 1; break;
            default: break;
            }
            general.cost = cost;
        }

        // 2. Abilities whose numbers differ in the original code.
        // Genie: 1~5 random == 2 -> 20% (v15 step 7, FUN_0040a9ba). fheroes2 had 10%.
        setAbilityPercentage( monsterData[Monster::GENIE], fheroes2::MonsterAbilityType::ENEMY_HALVING, 20 );
        // Dwarf: 0~4 random == 1 -> 20% (v16, FUN_0040e464). fheroes2 had 25%.
        // Which spells it covers still differs (HoMM1: Lightning, Slow, Curse, Turn Undead, Dispel, Berserk, Paralyze) -> spell step.
        setAbilityPercentage( monsterData[Monster::DWARF], fheroes2::MonsterAbilityType::MAGIC_RESISTANCE, 20 );
        // Phoenix: no fire/lightning immunity in HoMM1. Area damage spells skip only creature 23 (dragon) and the single-target
        // resistance check knows only dragon and dwarf (v16; FUN_0040f7cd, FUN_0040fbff, FUN_00410038, FUN_0041032b, FUN_0040e464).
        removeAbility( monsterData[Monster::PHOENIX], fheroes2::MonsterAbilityType::ELEMENTAL_SPELL_IMMUNITY );
    }

    float attackDefenseMultiplier( int difference )
    {
        difference = std::clamp( difference, -20, 20 );
        float value = 0;
        std::memcpy( &value, &attackDefenseTableBits[difference + 20], sizeof( value ) );
        return value;
    }

    uint32_t finishDamage( const double baseDamage, const int attack, const int defense, const int extraDefense, const int luck, const bool shooterInMelee )
    {
        float damage = static_cast<float>( attackDefenseMultiplier( attack - ( defense + extraDefense ) ) * static_cast<float>( baseDamage ) );
        if ( luck > 0 ) {
            damage = static_cast<float>( damage * 2.0f );
        }
        if ( luck < 0 ) {
            damage = static_cast<float>( damage / 2.0f );
        }
        if ( shooterInMelee ) {
            damage = static_cast<float>( damage / 2.0f );
        }
        return static_cast<uint32_t>( std::clamp( static_cast<int>( static_cast<double>( damage ) + 0.5 ), 1, 32000 ) );
    }

    int strikeDamage( const StrikeInput & in, const std::function<int( int, int )> & rnd, bool & halfTroops )
    {
        halfTroops = false;
        // Step 1: fild / fadd dword / fstp dword per creature.
        float base = 0;
        for ( int k = 0; k < in.count; ++k ) {
            int one = 0;
            if ( in.damageState == 1 ) {
                one = in.damageMin;
            }
            else if ( in.damageState == 3 ) {
                one = in.damageMax;
            }
            else {
                one = rnd( in.damageMin, in.damageMax );
            }
            base = static_cast<float>( static_cast<float>( one ) + base );
        }
        // Steps 2-5, each result stored as a 4-byte float (fstp dword).
        float damage = static_cast<float>( attackDefenseMultiplier( in.attack - ( in.targetDefense + in.extraDefense ) ) * base );
        if ( in.luck > 0 ) {
            damage = static_cast<float>( damage * 2.0f );
        }
        if ( in.luck < 0 ) {
            damage = static_cast<float>( damage / 2.0f );
        }
        if ( in.shooterInMelee ) {
            damage = static_cast<float>( damage / 2.0f );
        }
        if ( in.damageState == 2 ) {
            damage = static_cast<float>( damage / 2.0f );
        }
        // Step 6: fadd qword 0.5, __ftol (towards zero).
        int result = static_cast<int>( static_cast<double>( damage ) + 0.5 );
        // Step 7: genie.
        if ( in.creature == 0x1b && rnd( 1, 5 ) == 2 ) {
            const int half = ( in.targetCount + 1 ) / 2 * in.targetHp;
            if ( result < half ) {
                halfTroops = true;
                result = half;
            }
        }
        // Step 8.
        return std::clamp( result, 1, 32000 );
    }

